/** Machine translated draft; religious and linguistic review pending. */
internal object DuaBrxDraft7 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_praising_someone" to DuaText("सोरबा सासेखौ बाख्नायनायनाय समाव", "आं बेबादि आरो बेबादि सान्ना लायो, आरो अल्लाहआ बिनि सानरिखिसा, आरो आं अल्लाहनि सिगाङाव सोरबा सासेनि गोथारथिनि थाखाय रोखा खालामाखै।", "सोरबा सासेखौ बाख्नायनायनाय समाव, बांद्राय बुंनायनि सोलायै।", "पैगम्बर सल्लल्लाहु अलैहि वस्लमा बाख्नायनायनि बे नेमखौ फोरोंदोंमोन।"),
        "dua_being_praised" to DuaText("जेब्ला नों बाखनायजायो।", "ऐ अल्लाह, बिसोर मा बुङो बिनि थाखाय आंनो हिसाब हो आरो जायखौ बिसोर मिन्थिना गैया बिनि थाखाय आंखौ क्षमा खालाम।", "गावखौ बाख्नायनायखौ खोनानाय-सासे लोगोनि (आर. ए.) सर'।", "बाख्नायनाय जायोब्ला गोग्गानायनिफ्राय बारग'नो मोनसे राहा।"),
        "dua_non_muslim_sneezes" to DuaText("जेब्ला सासे मुस्लिम नङिआ हासुनो।", "अल्लाहआ नोंखौ लामा दिन्थि आरो नोंनि हाबाफोरखौ थि खालाम।", "जेब्ला सासे मुस्लिम नङिआ हासुनो आरो'अलहामदुलिल्लाह'बुङो।", "इहुदिफोरा पैगंबर स'लिह आलीह वसलमनि खाथियाव हासुनो हागौमोन आरो बियो'यारहमुकल्लाह'बुंगोन होन्ना मिजिंथियोमोन, आरो बियो बे बाथ्राखौ बुंगोन।"),
        "dua_reply_ahl_kitab_salam" to DuaText("सलाम अफ पीपल ऑफ द बुकखौ फिन होनाय।", "आरो नोंनि सायाव।", "जेब्ला बिजाबनि सुबुंफोरा सालामजों बरनायो।", "पैगंबर सल्लल्लाहु अलैहि वसल्लमनि बिथोन।"),
        "dua_fasting_invited" to DuaText("जेब्ला उपबास खालामनाय समाव लिंहरजायो", "आं उपबास खालामदों।", "जेब्ला उपबासनि समाव लिंहरनाय जायो, एबा जेब्ला सोरबा नोंथांजों नांलायलायलाय जायो।", "जुदि उपबास खालामग्रा मानसिया लिंहरनायखौ नाजावो, अब्ला बिथाङा आलासिनि थाखाय आरज गाबनांगौ।"),
        "dua_for_who_gave_drink" to DuaText("जायनो आंनो जाहोनाय जायो", "ऐ अल्लाह, जाय आंनो जाहैयो बिखौ जाहाजा आरो जाय आंनो लोंहो बिखौ लों।", "जायनो नोंखौ जाग्रा एबा लोंनाय होयो।", "पैगम्बर सल्लल्लाहु अलैहि वस्लमा बे दुआखौ अल-मक्दाद (रा.) नि थाखाय बानायदोंमोन।"),
        "dua_eid_greeting" to DuaText("ईदनि बरनायनाय।", "अल्लाहआ जोंनिफ्राय आरो नोंनिफ्राय (मोजां खामानिफोर) नाजाव।", "ईदनि सानाव सासेया सासेखौ-मोजां लोगोफोरनि (आर. ए.) सर'।", "लोगोफोरा बे बाथ्राखौ अब्ला बुंदोंमोन जेब्ला बिसोरो ईदआव लोगो मोनदोंमोन।"),
        "dua_wedding_night" to DuaText("निकाहनि उनाव हिनजाव गोदाननि थाखाय", "ऐ अल्लाह, आं नोंखौ बिनि मोजां आरो मिथिंगानि मोजांनि थाखाय सोङो जायजों नों बिखौ सोरजिदों मोन, आरो आं नोंनि सिङाव बिनि गाज्रि आरो मिथिंगानि गाज्रिनिफ्राय शरण नागिरो जायजों नों बिखौ सोरजिदों मोन।", "निकाहनि उनाव, आखाइखौ बिसिनि खर'आव दोन।", "पैगंबरनि सलियाह अलियाह वसलम फोरोंनाय-जुलिआव बोर होनाय।"),
        "dua_istisqa_ibadak" to DuaText("नोंनि मावसाफोर आरो जुनारफोरखौ दै हो।", "ऐ अल्लाह, नोंनि बान्दाफोर आरो जुनारफोरनो दै हो, नोंनि अननायखौ गोसारहो आरो नोंनि थैनाय हाखौ जिउ हो।", "अखा थाखाय सोंनाय (इस्तिस्का)।", "पैगम्बर सल्लल्लाहु अलैहि वस्लमा अखानि थाखाय बे दुआखौ बानायदोंमोन।"),
        "dua_seeing_clouds" to DuaText("गोसोम जोमैफोरखौ नाय।", "ऐ अल्लाह, आं नोंनि सिङाव बेनि गाज्रिनिफ्राय रैखा नागिरो।", "अख्राङाव गोसोम जोमैफोर नुजाखांनायनि उनाव; अखा हायोब्ला,'अल्लाहुम्मा सैयिबान नफिया'बुं।", "जोमैफोरखौ नुनानै, पैगम्बर सल्लल्लाहु अलैहि वस्लमा गावनि खामानिखौ नागारदोंमोन आरो बे दुआखौ बानायदोंमोन।"),
        "dua_jamarat" to DuaText("जमारातखौ अन्थाइ सौहोनाय।", "अल्लाहआ बयनिख्रुइबो देरसिन।", "मोनफ्रोम अन्थाइजों गारनाय।", "पैगम्बर सल्लल्लाहु अलैहि वस्लमा मोनफ्रोम अन्थाइजों तकबीरखौ बुंदोंमोन, बिनि उनाव सेथि आरो नैथि जामरानि उनाव किब्लाहखौ मोगा-मोगि जानानै मोनसे गोलाव दुआ बानायदोंमोन।"),
        "dua_rabbi_ainni" to DuaText("आंनि इसोर, आंखौ मदद खालाम आरो आंनि बेरेखायै नङा।", "आंनि इसोर, आंखौ मदद खालाम आरो आंनि बेरेखायै गुबुनफोरखौ मदद खालाम, आंखौ देरहाहो आरो गुबुनफोरखौ आंनि सायाव देरहासारहो, आंनि थाखाय बिथांखि ला आरो आंनि बेरेखायै बिथांखि दाखालाम, आंखौ लामा दिन्थि आरो आंनि थाखाय लामा दिन्थि आरो जाय आंनि सायाव गोरोन्थि खालामो बिनि बेरेखायै आंखौ मदद खालाम।", "पैगंबर सल्लल्लाहु अलैहि वस्लमनि मोनसे गुवार दुआ।", "मोनसे दुआ जाय धोरोम आरो बे मुलुगाव गासैबो मदद बुथुमो।"),
        "dua_ati_nafsi_taqwaha" to DuaText("आंनि जिउमाखौ बिनि तकवा हो।", "ऐ अल्लाह, आंनि जिउमाखौ बिनि गोथारथिखौ हो आरो बेखौ गोथार खालाम, मानोना नोंनो बेखौ गोथार खालामनो थाखाय साबसिन। नोंनो बेनि रैखाथिगिरि आरो बेनि मास्तर।", "गावखौ फोसाबनो आरो गोथार खालामनो थाखाय।", "पैगम्बर सल्लल्लाहु अलैहि वस्लमा बे दुआखौ बानायदोंमोन।"),
        "dua_iqsim_lana_khashyatik" to DuaText("नोंजों बेबादि गिनांगौखौ आंनो हो।", "ऐ अल्लाह, नोंजों जोंनि गेजेराव फैहैनो आरो नोंनि मानियाखौ मानिना थानो थाखाय नोंनो थोजासे गिनांगौ हो, नोंखौ नोंनि सोरगोआव लांफिननो थाखाय थोजासे मानिनाय, आरो बे मुलुगनि खैफोदफोरखौ जोंनि थाखाय गोरलै खालामनो थाखाय थोजासे रोखा। नों नोंखौ थांना दोनबाय थानायसिम जों जोंनि खोनानाय, जोंनि नुथाइ आरो जोंनि गोहोखौ रंजानो हो आरो बिसोरखौ जोंनि थाखाय अरायथा खालाम। जाय जोंनि सायाव गोरोन्थि खालामो, जोंनि सुथुरफोरनि बेरेखायै जोंनि मदद खालाम, जोंनि खैफोदखौ जोंनि धोरोमाव जानो नाङा, बे मुलुगखौ जोंनि बयनिख्रुइ देरसिन जिंगा एबा जोंनि गियाननि सिमा खालाम आरो जोंनि सायाव बैफोरफोरखौ दोननाङा जाय जोंनि सायाव जेबो अननाय दाखालामनो हाया।", "जेब्ला मोनसे ज'थायनिफ्राय ओंखारो-पैगंबर सल्लल्लाह अलैहि वस्लमा बे दुआखौ खालामालाबानो माब्लाबासो ओंखारो।", "धोरोम, बे मुलुग आरो उननि मोजांनि थाखाय मोनसे गुवार दुआ।"),
        "dua_infani_bima_allamtani" to DuaText("नों आंनो जायखौ फोरोंदों, बेजों आंनो मुलाम्फा हो।", "ऐ अल्लाह, नों आंनो जाय फोरोंदों, बेजों आंनो मुलाम्फा हो, आंनो मा मुलाम्फा जागोन बेखौ फोरों आरो आंनो गियानखौ बांहो।", "गियान नागिरनाय समाव एबा फरायनायनि सिगां।", "मुलामफा गोनां गियान आरो बेनि सायाव खामानि मावनायनि थाखाय मोनसे दुआ।"),
        "dua_jar_su" to DuaText("गाज्रि नसुंसेनिनिफ्राय रैखा खालाम।", "ऐ अल्लाह, आं अरायथा थाग्रा जायगायाव सासे गाज्रि नसुंसेनिफ्राय नोंनि सिङाव आश्रय नागिरो, मानोना नसुंसेनि दावबायनाया दावगाहोयो।", "गाज्रि नसुंसेनिफ्राय रैखाथिनि थाखाय।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लमा बेनिफ्राय आश्रय लानो बिथोन होदोंमोन।"),
        "dua_ishfi_abdak" to DuaText("सासे बेरामगोनां सुबुंनि हामनायनि थाखाय", "ऐ अल्लाह, नोंनि बान्दाखौ फाहाम जाहाथे बियो नोंनि थाखाय सुथुरखौ मोगा-मोगि जानो हायो एबा नोंनि थाखाय आरज गाबनो थाबाय थानो हायो।", "जब्रा सुबुंनि थाखाय जेब्ला बिखौ लोगो हमलाय।", "पैगम्बर सल्लल्लाहु अलैहि वस्लमा बेराम जानाय सुबुंफोरनि थाखाय बे बाथ्रा बुंनायखौ फोरोंदोंमोन।"),
        "dua_la_mania" to DuaText("नोंथाङा जाय होयो बेखौ रावबो होबथानो हाया।", "अल्लाहनि अनगा रावबो फुजिजानायनि मोन्थाइ गैया, सासेनि अनगा, बाहागोआरि गैयालासे। बिथांनिनो रायजो आरो बिथांनिनो बाख्नायनायनाय आरो गासिबो जिनिसनि सायाव बिथांनि गोहो दं। ऐ अल्लाह, नों जाय होयो बेखौ रावबो होबथानो हाया आरो जायखौ नोङो दोनखो, आरो जाय दोहोनि धोनआ नोंनि बेरेखायै जेबो मुलाम्फा नङा।", "गोनां आरज गाबनायनि उनाव।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लमा मोनफ्रोमबो गोनांथार आरज गाबनायनि उनाव बे बाथ्रा बुंदोंमोन।"),
        "dua_slaughtering" to DuaText("जेब्ला जुनारखौ बुथारनाय जायो।", "अल्लाहनि मुंजों, आरो अल्लाहआ बयनिख्रुइबो देरसिन।", "जेब्ला मोनसे जुनारखौ बावनाय एबा बुथारनाय जायो।", "पैगम्बर सल्लल्लाहु अलैहि वस्लमा बावसोमनाय समाव बिस्मिल्लाह आरो तकबीरखौ बुंदोंमोन।"),
        "dua_undressing" to DuaText("जि-जोमफोरखौ बोखारनाय समाव", "अल्लाहनि मुंजों।", "जि-जोम बोखारनाय समाव (गुसल एबा सोलायनो थाखाय)।", "बेयो जिन्ननि मेगन आरो सुबुंनि गावारि अंगफोरनि गेजेराव मोनसे फैसालि जायो।"),
        "dua_ilbas_jadidan" to DuaText("सोरबा गोदान जि गान्नाय नुनो मोन्नाय।", "गोदान गान्ना थां, बाखनायजाथाव जिउ खुं आरो सासे थैगिरि थै।", "सासे मुस्लिम फंबायखौ गोदान जि गान्नाय नुनो मोननायाव।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लमा उमर (रा.) खौ गोदान जि गान्नाय नुनानै बे दुआखौ खालामदोंमोन।"),
        "dua_hajj_la_riya" to DuaText("दिन्थिमहरनायनिफ्राय उदां हज", "ऐ अल्लाह, (बेखौ) मोनसे हज खालाम जेराव जेबो दिन्थिमहरनाय आरो मुंदांखा जानाय गैया।", "हजनि थांखि लानाय समाव गोसो गोनांनि थाखाय।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लमा हजनि समाव बे दुआखौ बानायदोंमोन।"),
        "dua_q_muslimayni_laka" to DuaText("इब्राहिम आरो इसमाइल (ए. एस.) नि दुआ-नोंखौ गाहायनि खालाम।", "जोंनि इसोर, नोंखौ आरो जोंनि फोलेरनिफ्राय नोंखौ सिबिनायनि थाखाय मोनसे हादोर बानाय। जोंनि सिबिथायनि आसार-खान्थिफोरखौ दिन्थि आरो जोंनि अननायखौ नाजाव। थारैनो, नों अननायनि आगजुगिरि, अनजाथाव।", "गावनि आरो गावनि फोलेरनि थाखाय मोनसे बावसोमनायनि दुआ।", "दुआआ काबा लुनाय समाव बानाय जादोंमोन।"),
        "dua_q_iftah_baynana" to DuaText("शु'ऐबनि दुआ (एएस)-जोंनि गेजेराव बिजिरगिरि।", "जोंनि इसोर, जोंनि आरो जोंनि सुबुंफोरनि गेजेराव सैथोजों बिजिर, आरो नों साबसिन बिजिरगिरि।", "सैथो आरो मिथिसारनि गेजेराव मोनसे बिजिरनायनि थाखाय।", "शु'अयब (ए. एस.) नि दुआ जेब्ला बिथांनि सुबुंफोरा बिथांखौ नेवसिगारदोंमोन।"),
        "dua_q_la_akuna_zahiran" to DuaText("मुसा (ए. एस.) नि दुआआ-माब्लाबाबो दायगिरिफोरनि हेफाजाबगिरि नङामोन।", "आंनि इसोर, नों आंनो होनाय अनथोबनि थाखाय, आं माब्लाबाबो दाय खालामग्राफोरनि हेफाजाबगिरि जानाय नङा।", "अल्लाहनि बोरनि थाखाय बाखनायनाय आरो गोरोन्थि खालामग्राफोरखौ मदद खालामैनि समायनाय।", "गावनि उनदाहा जानायनि उनाव मुसा (ए. एस.) नि समाय।"),
        "dua_q_nuh_unsurni" to DuaText("नूह (आ. स.) नि दुआ-आंखौ मदद खालाम, बिसोरो आंखौ नेवसिगारो।", "आंनि इसोर, आंखौ मदद खालाम, मानोना बिसोरो आंखौ नेवसिगारदोंमोन।", "जेब्ला सुबुंफोरा नोंखौ नेवसिगारो आरो सैथोखौ नेवसिगारो।", "नूह (ए. एस.) नि दुआ, जायनि फिन होनाय जादोंमोन।"),
        "dua_q_ihkum_bil_haqq" to DuaText("आंनि इसोर, सैथोजों बिजिर।", "आंनि इसोर, सैथोजों बिजिर। आरो जोंनि इसोरआ जोबोद अनजाथाव, जायनि मददखौ नों जायखौ बुंबाय बेनि बेरेखायै नागिरो।", "मिथिसार आरो गोरोन्थि दायफोरनि सिगाङाव।", "पैगंबर (स) नो मोनसे दुआ फोरोंदोंमोन।"),
        "dua_ghalabatid_dayn" to DuaText("दाहार आरो सुथुरफोरखौ सिफायनायनिफ्राय रैखा खालाम।", "ऐ अल्लाह, आं दाहारजों बोजाबोनायनिफ्राय, सुथुरजों गाग्लोब जानायनिफ्राय आरो सुथुरफोरनि गोग्गानायनिफ्राय नोंनि सिङाव शरण नागिरो।", "दाहार आरो सुथुरफोरनि गादबनायनिफ्राय रैखा।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लमा बे बाथ्राफोरनिफ्राय रैखा लायोमोन।"),
        "dua_faqr_qillah_dhillah" to DuaText("निखावरि आरो मानहानिनिफ्राय रैखा मोननो हानाय।", "ऐ अल्लाह, आं नोंखौ निखावरि, आंखाल आरो लाजिनिफ्राय, आरो गुबुनफोरखौ अनागारि खालामनाय एबा अनागारि जानायनिफ्राय रैखा खालामनो नागिरो।", "गोब्राब, गोसो जानाय आरो लाजिनिफ्राय रैखा जाना थानो।", "पैगंबर सल्लल्लाहु अलैहि वसल्लमजों फोरोंजानाय मोनसे आश्रय।"),
        "dua_five_things_new_muslim" to DuaText("क्षमा खालाम, अननाय हो, लामा दिन्थि, हामनाय, जगाय।", "ऐ अल्लाह, आंखौ बावगार, आंखौ अननाय, आंखौ लामा दिन्थि, आंनो मोजां राहा हो आरो आंनो राहा हो।", "पैगम्बर सल्लल्लाहु अलैहि वस्लमा गोदान मुसलमानफोरनो आरज गाबनायजों लोगोसे बे दुआखौ फोरोंदोंमोन।", "पैगम्बर सल्लल्लाहु अलैहि वस्लमा बुंदोंमोनः बे सोदोबफोरा बे मुलुग आरो उननि नोंखौ ज'खालामो।"),
        "dua_ruku_laka_raka_tu" to DuaText("इन रुकू-आं नोंखौ सिथाबदोंमोन।", "ऐ अल्लाह, आं नोंखौ सिबिनांदोंमोन, आं नोंखौ फोथायदोंमोन आरो आं नोंखौ सिबिनांदोंमोन। आंनि खोनानाय, आंनि नुथाइ, आंनि गोसो, आंनि बेगेंफोर आरो आंनि सिन्युफोरा नोंनि सिगाङाव गाहायसिन।", "रुकुवाव (जर'खायै गावआरि आरज गाबनायाव)।", "पैगम्बर सल्लल्लाहु अलैहि वस्लमा बेखौ रुकुवाव फरायदोंमोन।"),
        "dua_sujood_laka_sajadtu" to DuaText("सुजुदआव-नोंनो आं बिथोन होदोंमोन।", "ऐ अल्लाह, आं नोंखौ सिज'द खालामदों, आं नोंखौ फोथायदों आरो आं नोंखौ सिबिनांदोंमोन। आंनि मोखांआ बैनोखौ सिज'द खालामदों जाय बेखौ सोरजिदों, महर होदों आरो बिनि खोनानाय आरो नुथायखौ दिहुनदों। बरनायजानायआ अल्लाह, जाय सोरजिदोंफोरनि गेजेराव साबसिन।", "सुजूदआव (जर'खायै गावआरि आरज गाबनायाव)।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लमा बेखौ सुजूदआव फरायदोंमोन।"),
        "dua_ruku_sujood_subhanaka" to DuaText("नोंखौ गोग्गानाय, जोंनि इसोर-आंखौ बावगार।", "हे अल्लाह, जोंनि इसोर, नोंनो महिमा आरो नोंनो बाख्नायनाय। हे अल्लाह, आंखौ क्षमा खालाम।", "रुकू आरो सुजूदआव।", "आयशाः पैगम्बर सल्लल्लाहु अलैहि वस्लमा बेखौ गोबां समावनो रुकू आरो सुजूदआव बुङोमोन।"),
        "dua_q_musa_li_akhi" to DuaText("मुसा (ए. एस.) नि दुआ-आंखौ आरो आंनि फंबायखौ बावगार।", "आंनि इसोर, आंखौ आरो आंनि फंबायखौ बावगार आरो नोंखौ गावनि अननायाव थिसन, मानोना नोंनो अनजाथावनि गेजेराव बांसिन अनजाथाव।", "गावनि आरो गावनि फंबाय एबा मोजां मोनग्राफोरनि थाखाय बावगारनाय।", "हारून (एएस) नि थाखाय मुसा (एएस) नि दुआ।"),
        "dua_q_ufawwidu_amri" to DuaText("आं आंनि बाथ्राखौ अल्लाहनो बावनाय।", "आरो आं आंनि हाबाखौ अल्लाहनो बावनाय। थारैनो अल्लाहआ गावनि बान्दाफोरखौ नायग्रा।", "जेब्ला सुबुंफोरा नोंखौ हेंथा होयो आरो बे बाथ्राखौ अल्लाहनि सायाव दोननांगौ।", "फार'ननि सुबुंफोरनिफ्राय फोथायग्रानि बाथ्राफोर; अब्ला अल्लाहआ बिथांखौ बिसोरनि गाज्रि सानथांखिफोरनिफ्राय रैखा खालामदोंमोन।"),
        "dua_q_hawariyyun" to DuaText("सोलोंसाफोरनि दुआ-साखिफोरजों जोंखौ रेबगान्थ खालाम।", "ऐ जोंनि इसोर, जों नों जाय फोरमायदोंमोन, बेयाव फोथायदोंमोन आरो जों रसूलनि उनमोनस्लायदोंमोन, बेनिखायनो जोंफोरखौ साखिफोरनि गेजेराव रेबगान्थ खालाम।", "फोथायनायाव दिदोमथि आरो पैगंबरखौ उनसंनायनि थाखाय।", "ईसा (एएस) नि सोलोंसाफोरनि दुआ।"),
        "dua_q_la_tukhzini" to DuaText("इब्राहिमनि दुआ (आ. स.)-आंखौ अनागारि खालाम।", "आरो जाय सानाव बिसोर फिन जोनोम मोनफिनगोन, बे सानाव आंखौ लाजि होनाङा।", "फिन फिन फिन फिन फिन फिन फिन फिननाय सानाव लाजिनिफ्राय रैखा जाना थानो।", "उननि थाखाय इब्राहिम (आ. स.) नि दुआ।"),
        "dua_iftar_laka_sumtu" to DuaText("इफ्तार-नोंनि थाखाय आं गोथाव।", "ऐ अल्लाह, आं नोंनि थाखाय रोजा दोनो आरो नोंनि राहाजों आं आंनि रोजाखौ सिफायो।", "जेब्ला उपबासखौ सिफायो (मुंदांखा इफ्तार दुआ)।", "पैगम्बर स'लिअल्लाह वसीमआ इफ्तारआव बेखौ बुंदोंमोन। बेयो गुबुन सल'बाथाइफोरजों गोख्रों जानाय मोनसे मुर्सल सल'बाख्नायनाय; इफ्तारआव बेखौ फरायनाया हनाफीफोर आरो गोबांसिन सुबुंफोरनि हुदा।"),
        "dua_iftar_ibn_umar" to DuaText("इफ्तार-नोंनि गुवार अननायजों, आंखौ बावगार।", "ऐ अल्लाह, आं नोंखौ नोंनि अननायजों सोङो जाय आंखौ क्षमा खालामनो थाखाय गासैबो बाथ्राफोरखौ लाफायो।", "इफ्तारआव-अब्दुल्ला इब्न अम्र (रा.) आ बे दुआखौ बानायदोंमोन; इफ्तारआव सासे उपबास खालामग्रा सुबुंनि दुआखौ नेवसिगारनाय जाया।", "हादीसः इफ्तारनि समाव उपबास खालामनाय सुबुंनि दुआखौ नेवसिजाया।"),
        "dua_inni_saim" to DuaText("जेब्ला उपबास खालामनाय समाव गोसो गुदुं जायो", "आं उपबास खालामदों, आं उपबास खालामदों।", "जेब्ला सोरबा नोंखौ अनागारि खालामो एबा उपबासनि समाव नोंजों नांलाय-नांलाय खालामो।", "पैगम्बर सल्लल्लाह अलैहि वस्लमा बुंदोंमोनः उपबासआ मोनसे ढाला, बेनिखायनो उपबास खालामग्रा मानसिया गाज्रि रायज्लायनो नाङा एबा गियान गैयालासे खामानि मावनो नाङा-जुदि सोरबा नांलाय-नांलाय जायो, अब्ला बेखौ खेबनै बुं।"),
    )
}
